CREATE TABLE IF NOT EXISTS ca_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(64) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(16) NOT NULL DEFAULT 'user',enabled TINYINT NOT NULL DEFAULT 1,session_version INT NOT NULL DEFAULT 1,phone VARCHAR(11) NULL,UNIQUE KEY phone_idx(phone),created DOUBLE NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ca_settings (`name` VARCHAR(100) PRIMARY KEY,value LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ca_meters (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,label VARCHAR(100) NOT NULL,school_code VARCHAR(40) NOT NULL,account_secret TEXT NOT NULL,college_note VARCHAR(100) NOT NULL DEFAULT '',roomverify VARCHAR(150) NOT NULL DEFAULT '',business_type VARCHAR(10) NOT NULL DEFAULT '0',command VARCHAR(64) NOT NULL DEFAULT 'JBSWaterElecService',enabled TINYINT NOT NULL DEFAULT 1,revision INT NOT NULL DEFAULT 1,settings LONGTEXT NOT NULL,next_query DOUBLE NOT NULL DEFAULT 0,last_tick DOUBLE NOT NULL DEFAULT 0,created DOUBLE NOT NULL,KEY owner_idx(user_id),FOREIGN KEY(user_id) REFERENCES ca_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ca_channels (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,meter_id BIGINT UNSIGNED NOT NULL,kind VARCHAR(30) NOT NULL,enabled TINYINT NOT NULL DEFAULT 0,secret TEXT NOT NULL,mode VARCHAR(16) NOT NULL DEFAULT 'fixed',UNIQUE KEY channel_idx(meter_id,kind),FOREIGN KEY(meter_id) REFERENCES ca_meters(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ca_state (meter_id BIGINT UNSIGNED NOT NULL,`name` VARCHAR(180) NOT NULL,value LONGTEXT NOT NULL,PRIMARY KEY(meter_id,`name`),FOREIGN KEY(meter_id) REFERENCES ca_meters(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ca_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,meter_id BIGINT UNSIGNED NOT NULL,day VARCHAR(10) NOT NULL,ts DOUBLE NOT NULL,kind VARCHAR(20) NOT NULL,state VARCHAR(20) NOT NULL DEFAULT 'started',error VARCHAR(255),final_day VARCHAR(10) GENERATED ALWAYS AS (CASE WHEN kind='final' THEN day ELSE NULL END) STORED,UNIQUE KEY final_idx(meter_id,final_day),KEY quota_idx(meter_id,day),FOREIGN KEY(meter_id) REFERENCES ca_meters(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ca_readings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,meter_id BIGINT UNSIGNED NOT NULL,attempt_id BIGINT UNSIGNED UNIQUE NOT NULL,revision INT NOT NULL,series CHAR(64) NOT NULL,ts DOUBLE NOT NULL,balance DOUBLE NOT NULL,balance_raw VARCHAR(80) NULL,balance_exact DECIMAL(18,6) NULL,meter_ts DOUBLE NULL,room VARCHAR(255) NOT NULL,quality VARCHAR(40) NOT NULL,analysis LONGTEXT NOT NULL,KEY history_idx(meter_id,revision,ts),FOREIGN KEY(meter_id) REFERENCES ca_meters(id),FOREIGN KEY(attempt_id) REFERENCES ca_attempts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ca_intervals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,meter_id BIGINT UNSIGNED NOT NULL,revision INT NOT NULL,series CHAR(64) NOT NULL,start DOUBLE NOT NULL,ts DOUBLE NOT NULL,hours DOUBLE NOT NULL,energy DOUBLE NOT NULL,energy_exact DECIMAL(18,6) NULL,energy_lower DECIMAL(18,6) NULL,energy_upper DECIMAL(18,6) NULL,usable TINYINT NOT NULL,tag VARCHAR(40) NOT NULL,KEY model_idx(meter_id,revision,ts),FOREIGN KEY(meter_id) REFERENCES ca_meters(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ca_residuals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,meter_id BIGINT UNSIGNED NOT NULL,revision INT NOT NULL,series CHAR(64) NOT NULL,ts DOUBLE NOT NULL,hours DOUBLE NOT NULL,residual DOUBLE NOT NULL,KEY model_idx(meter_id,revision,ts)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ca_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,meter_id BIGINT UNSIGNED NOT NULL,ts DOUBLE NOT NULL,kind VARCHAR(50) NOT NULL,details LONGTEXT NOT NULL,KEY owner_ts(meter_id,ts)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ca_jobs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,meter_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,revision INT NOT NULL,created DOUBLE NOT NULL,state VARCHAR(20) NOT NULL DEFAULT 'queued',message VARCHAR(255),attempt_id BIGINT UNSIGNED,KEY queue_idx(state,created),FOREIGN KEY(meter_id) REFERENCES ca_meters(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ca_outbox (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,meter_id BIGINT UNSIGNED NOT NULL,revision INT NOT NULL,unique_key VARCHAR(200) NOT NULL,channel VARCHAR(30) NOT NULL,day VARCHAR(10) NOT NULL,created DOUBLE NOT NULL,expires DOUBLE NOT NULL,state VARCHAR(30) NOT NULL DEFAULT 'queued',payload LONGTEXT NOT NULL,request_id VARCHAR(128),attempts INT NOT NULL DEFAULT 0,details VARCHAR(255),incident CHAR(32),channel_version INT NOT NULL DEFAULT 0,UNIQUE KEY dedupe_idx(meter_id,unique_key),KEY queue_idx(state,created)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ca_auth_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ip_hash CHAR(64) NOT NULL,ts DOUBLE NOT NULL,kind VARCHAR(20) NOT NULL,KEY throttle_idx(ip_hash,kind,ts)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS ca_user_channels (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,kind VARCHAR(30) NOT NULL,enabled TINYINT NOT NULL DEFAULT 0,secret TEXT NOT NULL,mode VARCHAR(16) NOT NULL DEFAULT 'fixed',templates LONGTEXT NOT NULL,config_version INT NOT NULL DEFAULT 1,UNIQUE KEY user_kind(user_id,kind),FOREIGN KEY(user_id) REFERENCES ca_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ca_channel_tests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,kind VARCHAR(30) NOT NULL,created DOUBLE NOT NULL,state VARCHAR(30) NOT NULL,details VARCHAR(255),request_id VARCHAR(128),KEY owner_created(user_id,created)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ca_otp (id CHAR(48) PRIMARY KEY,phone VARCHAR(11) NOT NULL,purpose VARCHAR(16) NOT NULL,user_id BIGINT UNSIGNED NULL,code_hash CHAR(64) NOT NULL,session_hash CHAR(64) NOT NULL,ip_hash CHAR(64) NOT NULL,created DOUBLE NOT NULL,expires DOUBLE NOT NULL,attempts INT NOT NULL DEFAULT 0,state VARCHAR(20) NOT NULL,request_id VARCHAR(128),KEY phone_created(phone,created),KEY ip_created(ip_hash,created),KEY created_idx(created)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS ca_forecast_runs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,meter_id BIGINT UNSIGNED NOT NULL,revision INT NOT NULL,series CHAR(64) NOT NULL,anchor_id BIGINT UNSIGNED NOT NULL,origin DOUBLE NOT NULL,model_version VARCHAR(50) NOT NULL,policy_version VARCHAR(50) NOT NULL,snapshot LONGTEXT NOT NULL,UNIQUE KEY anchor_idx(anchor_id),KEY sequence_idx(meter_id,revision,series,origin)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ca_forecast_evaluations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,forecast_id BIGINT UNSIGNED NOT NULL,horizon_group INT NOT NULL,validated_at DOUBLE NOT NULL,actual_hours DOUBLE NOT NULL,actual_kwh DECIMAL(18,6) NULL,error_kwh DOUBLE NULL,status VARCHAR(40) NOT NULL,UNIQUE KEY once_idx(forecast_id,horizon_group)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ca_recharge_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,meter_id BIGINT UNSIGNED NOT NULL,revision INT NOT NULL,series CHAR(64) NOT NULL,effective_ts DOUBLE NOT NULL,quantity DECIMAL(18,6) NULL,status VARCHAR(20) NOT NULL,source VARCHAR(100) NOT NULL,KEY sequence_idx(meter_id,revision,series,effective_ts)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ca_schedule_decisions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,meter_id BIGINT UNSIGNED NOT NULL,created DOUBLE NOT NULL,decision LONGTEXT NOT NULL,KEY owner_ts(meter_id,created)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
